<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Practical clinical support and cohort learning</div>
      </div>
    </div>
    <nav class="nav" aria-label="Primary">
      <a href="index.html">Welcome</a>
      <a href="about.html">Why work together</a>
      <a href="approach.html">Method</a>
      <a href="book.html">Book</a>
      <a href="contact.html" style="background:var(--accent);color:white;padding:8px 12px;border-radius:8px;text-decoration:none">Reach out</a>
    </nav>
  </header>

  <main class="hero">
    <div class="wrap reveal" data-reveal>
      <h1>Areas I commonly support</h1>
      <p style="color:var(--muted);margin-top:6px">Focused, practical work for life transitions, relationships, and recurring patterns — offered individually or in short cohorts when people want peer structure.</p>
    </div>

    <div class="wrap">
      <div class="row">
        <div class="panel reveal" data-reveal>
          <h3 style="margin-top:0">Specialties</h3>
          <div class="list" style="margin-top:12px">
            <div class="chip">Anxiety and worry that feels stuck</div>
            <div class="chip">Midlife & role transitions</div>
            <div class="chip">Relationship tension & communication</div>
            <div class="chip">New-parent adjustment</div>
            <div class="chip">Workplace stress & boundaries</div>
            <div class="chip">Decision-making during big changes</div>
          </div>

          <h4 style="margin-top:14px">How I think about problems</h4>
          <p style="color:var(--muted)">I look for leverage points: small adjustments that reduce friction day-to-day. We test changes and see what helps. When helpful, we also use short cohorts to practice skills with peer support and facilitator guidance.</p>
        </div>

        <aside class="panel reveal" data-reveal>
          <h3 style="margin-top:0">Quick Session Planner</h3>
          <div class="planner">
            <label for="concern-s">Main concern</label>
            <input id="concern-s" placeholder="What brings you here?">
            <label for="goal-s">Three-month aim</label>
            <input id="goal-s" placeholder="A practical, observable change">
            <label for="format-s">Format</label>
            <select id="format-s"><option>Individual</option><option>Cohort</option><option>Virtual</option></select>
            <div style="display:flex;gap:8px;margin-top:10px">
              <button class="btn strong" id="build-s">Make plan</button>
              <button class="btn" id="copy-s">Copy</button>
            </div>
            <pre id="summary-s" class="summary">Plan will appear here.</pre>
            <div style="margin-top:10px"><a href="{{PRIMARY_CTA_URL}}" class="btn" style="background:#eef6f4;padding:8px 10px;border-radius:8px;text-decoration:none;color:var(--primary)">Request a consult</a></div>
          </div>
        </aside>
      </div>

      <div class="reveal" data-reveal style="margin-top:18px">
        <h3>Referral & limits</h3>
        <p style="color:var(--muted)">If your needs are outside of my scope (e.g., specialized neuropsychological testing, immediate crisis intervention), I will discuss referrals. I respect confidentiality and discuss limits at intake.</p>
      </div>
    </div>
  </main>

  <footer style="padding:22px 20px;color:var(--muted)">
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
        <div>
          <strong>{{BUSINESS_NAME}}</strong><br>
          <span>{{CITY}}, {{STATE}}</span>
        </div>
        <div style="text-align:right">{ {PHONE} } | {{EMAIL}}</div>
      </div>
      <div style="margin-top:12px;font-size:13px">Crisis notice: If you are in immediate danger or an emergency, call local emergency services. This practice does not provide emergency services.</div>
    </div>
  </footer>

  <script>
    (function(){
      // reveal
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduced){ document.querySelectorAll('[data-reveal]').forEach(e=>e.classList.add('is-visible')); }
      else{ const io = new IntersectionObserver((es)=>es.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('is-visible'); }),{threshold:0.12}); document.querySelectorAll('[data-reveal]').forEach(e=>io.observe(e)); }

      // planner
      const build = document.getElementById('build-s');
      const copy = document.getElementById('copy-s');
      const sum = document.getElementById('summary-s');
      function buildText(){
        const c = (document.getElementById('concern-s').value||'').trim();
        const g = (document.getElementById('goal-s').value||'').trim();
        const f = (document.getElementById('format-s').value||'').trim();
        const lines = [];
        lines.push('{{BUSINESS_NAME}} — Session Snapshot');
        lines.push('Focus: ' + (c||'[not specified]'));
        lines.push('3-month aim: ' + (g||'[not specified]'));
        lines.push('Format: ' + f);
        lines.push('Book: ' + '{{PRIMARY_CTA_URL}}');
        return lines.join('\n');
      }
      build.addEventListener('click',()=>{ sum.textContent = buildText(); });
      copy.addEventListener('click',async ()=>{ try{ await navigator.clipboard.writeText(sum.textContent); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1200);}catch(e){ alert('Copy failed'); } });
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--accent:#b04adf;--muted:#6b7280}
    body{margin:0;font-family:Inter, system-ui, -apple-system,'Segoe UI',Roboto,Arial;background:var(--bg);color:#0b1220}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid #eef2f7}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    .hero{padding:40px 20px;background-image:url('assets/img/pattern.svg');background-size:260px}
    .wrap{max-width:980px;margin:0 auto;padding:0 20px}
    h1{margin:0 0 6px}

    .steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .step{background:#fff;padding:18px;border-radius:12px;border:1px solid #f1eef9}
    .meta{color:var(--muted);font-size:14px}

    .reveal{opacity:0;transform:translateY(16px);transition:opacity 420ms cubic-bezier(.2,.9,.26,1),transform 420ms cubic-bezier(.2,.9,.26,1)}
    .reveal.is-visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .reveal{opacity:1;transform:none;transition:none} }

    .planner{margin-top:18px;background:#fff;padding:16px;border-radius:12px;border:1px solid #eef2f6}
    .planner label{display:block;margin-top:10px;font-weight:600}
    .planner input,.planner textarea,.planner select{width:100%;padding:10px;border-radius:8px;border:1px solid #e8eef6}
    .btn{padding:10px 12px;border-radius:10px;border:none;cursor:pointer}
    .btn.primary{background:var(--accent);color:white}
    pre.summary{background:#081226;color:#e6f3ff;padding:12px;border-radius:8px;margin-top:12px}

    @media (max-width:880px){.steps{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><div style="width:44px;height:44px;background:var(--accent);border-radius:10px;color:white;display:flex;align-items:center;justify-content:center;font-weight:700">T</div><div><strong>{{BUSINESS_NAME}}</strong></div></div>
    <nav aria-label="Main">
      <a href="index.html">Home</a>
      <a href="specialties.html">Areas</a>
      <a href="about.html">About</a>
      <a href="fees.html">Fees</a>
    </nav>
  </header>

  <main class="hero">
    <div class="wrap reveal" data-reveal>
      <h1>How I structure therapy</h1>
      <p class="meta">A pragmatic, collaborative process — I help clients translate concern into steps, and then test those steps in day-to-day life.</p>
    </div>

    <div class="wrap">
      <div class="steps">
        <div class="step reveal" data-reveal>
          <h3>1. Map</h3>
          <p class="meta">We map the problem together: what's keeping it alive and what small changes might shift the pattern.</p>
        </div>
        <div class="step reveal" data-reveal>
          <h3>2. Try</h3>
          <p class="meta">We pick one or two experiments: concrete actions you can try between sessions and report back on.</p>
        </div>
        <div class="step reveal" data-reveal>
          <h3>3. Reflect</h3>
          <p class="meta">We review what worked, adjust, and build momentum. When helpful, cohorts add a practice space with peer feedback.</p>
        </div>
      </div>

      <div class="reveal" data-reveal style="margin-top:22px">
        <h3>Session rhythm</h3>
        <p class="meta">Most people start weekly, then move to biweekly or occasional check-ins as goals shift. Cohorts run on a set schedule so members can practice together.</p>
      </div>

      <div class="planner reveal" data-reveal>
        <h3 style="margin-top:0">Session Planner</h3>
        <label for="concern-a">What feels most urgent?</label>
        <input id="concern-a" placeholder="Briefly describe">
        <label for="why-a">Why now?</label>
        <input id="why-a" placeholder="What changed or pushed you here?">
        <label for="freq-a">Preferred pace</label>
        <select id="freq-a"><option>Weekly</option><option>Biweekly</option><option>Monthly</option></select>
        <div style="margin-top:10px;display:flex;gap:8px">
          <button class="btn primary" id="build-a">Create summary</button>
          <button class="btn" id="copy-a">Copy</button>
        </div>
        <pre id="summary-a" class="summary">Summary will appear here.</pre>
      </div>

      <div class="reveal" data-reveal style="margin-top:18px">
        <h3>Boundaries, confidentiality, and crisis</h3>
        <p class="meta">Therapy is confidential with legal exceptions (e.g., imminent harm). I do not provide emergency services. If you are in crisis, call local emergency services or a crisis hotline. We discuss limits, fees, and scheduling during intake.</p>
      </div>

      <div class="reveal" data-reveal style="margin-top:18px">
        <a href="{{PRIMARY_CTA_URL}}" class="btn primary" style="text-decoration:none">Request a brief consult</a>
      </div>

    </div>
  </main>

  <footer style="padding:20px;color:var(--muted)">
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
        <div><strong>{{BUSINESS_NAME}}</strong><div style="color:var(--muted)">{{CITY}}, {{STATE}}</div></div>
        <div style="text-align:right">{{PHONE}} | {{EMAIL}}</div>
      </div>
      <div style="margin-top:12px;font-size:13px;color:var(--muted)">If you need immediate help, call local emergency services. This practice is not an emergency service.</div>
    </div>
  </footer>

  <script>
    (function(){
      // reveal
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){ document.querySelectorAll('[data-reveal]').forEach(e=>e.classList.add('is-visible')); }
      else{ const io = new IntersectionObserver((entries)=>entries.forEach(en=>{ if(en.isIntersecting) en.target.classList.add('is-visible'); }),{threshold:0.12}); document.querySelectorAll('[data-reveal]').forEach(e=>io.observe(e)); }

      // planner
      const build = document.getElementById('build-a');
      const copy = document.getElementById('copy-a');
      const sum = document.getElementById('summary-a');
      function make(){
        const c = (document.getElementById('concern-a').value||'').trim();
        const w = (document.getElementById('why-a').value||'').trim();
        const f = (document.getElementById('freq-a').value||'').trim();
        const lines = [];
        lines.push('{{BUSINESS_NAME}} — Initial Snapshot');
        lines.push('Presenting: ' + (c||'[not specified]'));
        if(w) lines.push('Why now: ' + w);
        lines.push('Suggested pace: ' + f);
        lines.push('Contact: {{PHONE}} | {{EMAIL}}');
        lines.push('Book: {{PRIMARY_CTA_URL}}');
        return lines.join('\n');
      }
      build.addEventListener('click',()=>{ sum.textContent = make(); });
      copy.addEventListener('click',async ()=>{ try{ await navigator.clipboard.writeText(sum.textContent); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1300);}catch(e){ alert('Copy failed'); } });
    })();
  </script>
</body>
